import { useState } from "react";

export default function App() {
  const [todos] = useState([
    { id: 1, text: "A", done: false },
    { id: 2, text: "B", done: true },
    { id: 3, text: "C", done: false },
  ]);
  const left = todos.filter((t) => !t.done).length;
  return (
    <div>
      <p id="left">Left: {left}</p>
    </div>
  );
}
